    {
        return new[]
        {
            (byte)((increment >> 24) & 0x7f), (byte)(increment >> 16),
            (byte)(increment >> 8), (byte)increment,
        };
    }

    private void OnHeaders(uint streamId, bool endStream, byte[] block)
    {
        List<(string, string)> headers = decoder.Decode(block);
        var metadata = new Dictionary<string, string>();
        string status = null;
        string message = null;
        foreach ((string name, string value) in headers)
        {
            if (name == "grpc-status")
            {
                status = value;
            }
            else if (name == "grpc-message")
            {
                message = value;
            }
            else if (name == "grpc-encoding")
            {
                if (value == "gzip")
                {
                    decompressIn.Add(streamId);
                }
            }
            else if (name.StartsWith(":") || name == "content-type" || name == "grpc-accept-encoding")
            {
                // transport-owned: not metadata
            }
            else if (!metadata.ContainsKey(name))
            {
                metadata[name] = value;
            }
        }
        bool first = headersSeen.Add(streamId);
        if (endStream && status != null)
        {
            EmitTrailersFrame(streamId, long.Parse(status),
                Uri.UnescapeDataString(message ?? ""), metadata);
        }
        else if (first)
        {
            EmitHeadersFrame(streamId, metadata);
            if (endStream)
            {
                EmitTrailersFrame(streamId, 2, "missing grpc-status", metadata);
            }
        }
        else if (endStream)
        {
            EmitTrailersFrame(streamId, 2, "missing grpc-status", metadata);
        }
    }

    private void DrainMessages(uint streamId)
    {
        MemoryStream buf = dataBuffers[streamId];
        byte[] data = buf.ToArray();
        int off = 0;
        while (data.Length - off >= 5)
        {
            long mlen = ((long)data[off + 1] << 24) | ((long)data[off + 2] << 16)
                | ((long)data[off + 3] << 8) | (uint)data[off + 4];
            if (data.Length - off - 5 < mlen)
            {
                break;
            }
            int compressed = data[off];
            byte[] message = data[(off + 5)..(off + 5 + (int)mlen)];
            off += 5 + (int)mlen;
            if (compressed == 1 || decompressIn.Contains(streamId))
            {
                message = Gunzip(message);
            }
            Emit(Wire.FrameData, streamId, message);
        }
        buf.SetLength(0);
        buf.Write(data, off, data.Length - off);
    }

    private static byte[] Gunzip(byte[] data)
    {
        using var input = new MemoryStream(data);
        using var gz = new GZipStream(input, CompressionMode.Decompress);
        using var output = new MemoryStream();
        gz.CopyTo(output);
        return output.ToArray();
    }

    private static byte[] Gzip(byte[] data)
    {
        using var output = new MemoryStream();
        using (var gz = new GZipStream(output, CompressionMode.Compress))
        {
            gz.Write(data, 0, data.Length);
        }
        return output.ToArray();
    }

    public void Send(byte[] message)
    {
        if (message.Length < 9)
        {
            throw new InvalidOperationException("short frame");
        }
        int type = message[0];
        uint streamId = (uint)((message[1] << 24) | (message[2] << 16) | (message[3] << 8) | message[4]);
        int flen = (message[5] << 24) | (message[6] << 16) | (message[7] << 8) | message[8];
        byte[] payload = message[9..(9 + flen)];
        switch (type)
        {
            case Wire.FrameHeaders:
            {
                Codec.Headers headers = Codec.ParseHeaders(payload);
                string path = headers.Path ?? "";
                Dictionary<string, string> metadata = headers.Metadata;
                lock (cond)
                {
                    streamWindows.TryAdd(streamId, peerInitialWindow);
                }
                if (metadata.TryGetValue("grpc-encoding", out string enc) && enc == "gzip")
                {
                    compressOut[streamId] = true;
                }
                var block = new MemoryStream();
                block.WriteByte(0x83); // :method: POST
                block.WriteByte((byte)(scheme == "https" ? 0x87 : 0x86)); // :scheme
                WriteLiteralIndexedName(block, 4, path); // :path
                WriteLiteralIndexedName(block, 1, authority); // :authority
                WriteLiteralIndexedName(block, 31, "application/grpc"); // content-type
                WriteLiteralNewName(block, "grpc-accept-encoding", "gzip,identity");
                WriteLiteralNewName(block, "te", "trailers");
                foreach (KeyValuePair<string, string> e in metadata)
                {
                    string key = e.Key.ToLowerInvariant();
                    WriteLiteralNewName(block, key, key == "grpc-encoding" ? "gzip" : e.Value);
                }
                WriteFrame(H2Headers, FlagEndHeaders, streamId, block.ToArray());
                break;
            }
            case Wire.FrameData:
            {
                bool compressed = compressOut.GetValueOrDefault(streamId);
                byte[] body = compressed ? Gzip(payload) : payload;
                byte[] wire = new byte[5 + body.Length];
                wire[0] = (byte)(compressed ? 1 : 0);
                wire[1] = (byte)(body.Length >> 24);
                wire[2] = (byte)(body.Length >> 16);
                wire[3] = (byte)(body.Length >> 8);
                wire[4] = (byte)body.Length;
                Array.Copy(body, 0, wire, 5, body.Length);
                int sent = 0;
                while (sent < wire.Length)
                {
                    int allowance;
                    lock (cond)
                    {
                        while (!closed && (connWindow <= 0
                            || streamWindows.GetValueOrDefault(streamId, peerInitialWindow) <= 0))
                        {
                            Monitor.Wait(cond);
                        }
                        if (closed)
                        {
                            throw new IOException("transport closed");
                        }
                        long sw = streamWindows.GetValueOrDefault(streamId, peerInitialWindow);
                        allowance = (int)Math.Min(Math.Min(connWindow, sw),
                            Math.Min(MaxFramePayload, wire.Length - sent));
                        connWindow -= allowance;
                        streamWindows[streamId] = sw - allowance;
                    }
                    WriteFrame(H2Data, 0, streamId, wire[sent..(sent + allowance)]);
                    sent += allowance;
                }
                break;
            }
            case Wire.FrameHalfClose:
                WriteFrame(H2Data, FlagEndStream, streamId, Array.Empty<byte>());
                break;
            case Wire.FrameRst:
                WriteFrame(H2RstStream, 0, streamId, new byte[] { 0, 0, 0, 8 });
                break;
            default:
                // Trailers never travel client -> server here.
                break;
        }
    }

    public byte[] Recv()
    {
        if (queue.TryTake(out byte[] msg, Timeout.Infinite))
        {
            return msg;
        }
        throw new EndOfStreamException("transport closed");
    }

    public void Close()
    {
        try
        {
            socket.Close();
        }
        catch (Exception)
        {
            // already closed
        }
    }
}
